{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2127-09-05 23:33:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ll be taking care of you tonight. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2127-09-05 23:35:00",
      "speaker": "Patient",
      "text": "Hi, doctor. I’ve had this pain in my belly, right in the middle, going up toward my chest. It was really bad yesterday. I also threw up and haven’t had a bowel movement in two days."
    },
    {
      "turn_number": 3,
      "time": "2127-09-05 23:37:00",
      "speaker": "Doctor",
      "text": "I see. Is the pain sharp or more like a cramp? And has your belly felt bloated?"
    },
    {
      "turn_number": 4,
      "time": "2127-09-05 23:38:30",
      "speaker": "Patient",
      "text": "It’s sharp and crampy. And yes, my stomach is very swollen. I feel full even though I haven’t eaten much."
    },
    {
      "turn_number": 5,
      "time": "2127-09-05 23:40:00",
      "speaker": "Doctor",
      "text": "Okay. Any burning when you pee? Or more frequent urination?"
    },
    {
      "turn_number": 6,
      "time": "2127-09-05 23:41:20",
      "speaker": "Patient",
      "text": "Yes, I’ve been going a lot and it burns. That started a few days ago."
    },
    {
      "turn_number": 7,
      "time": "2127-09-05 23:43:00",
      "speaker": "Doctor",
      "text": "Thanks. We’ve done some tests. Your urine shows signs of infection, so we’ve started you on antibiotics. We also did a CT scan of your belly."
    },
    {
      "turn_number": 8,
      "time": "2127-09-05 23:45:00",
      "speaker": "Patient",
      "text": "What did it show? Is it serious?"
    },
    {
      "turn_number": 9,
      "time": "2127-09-05 23:46:30",
      "speaker": "Doctor",
      "text": "The scan shows a partial blockage in your small intestine. There’s a spot in the lower right side where the bowel narrows. We see a long, dense object—about 4.7 cm—likely a foreign body causing the blockage."
    },
    {
      "turn_number": 10,
      "time": "2127-09-05 23:48:00",
      "speaker": "Patient",
      "text": "A foreign body? I didn’t swallow anything like that!"
    },
    {
      "turn_number": 11,
      "time": "2127-09-05 23:49:30",
      "speaker": "Doctor",
      "text": "It might be something you ate without realizing. The good news is it’s a partial blockage, not complete. We’re not planning surgery right now. Instead, we’ll keep you on bowel rest—no food by mouth—and give you fluids through your IV."
    },
    {
      "turn_number": 12,
      "time": "2127-09-05 23:51:00",
      "speaker": "Patient",
      "text": "So I can’t eat at all?"
    },
    {
      "turn_number": 13,
      "time": "2127-09-05 23:52:20",
      "speaker": "Doctor",
      "text": "Not for now. We need to let your bowel rest so the swelling goes down. We’ll monitor your symptoms and repeat imaging if needed."
    },
    {
      "turn_number": 14,
      "time": "2127-09-05 23:54:00",
      "speaker": "Patient",
      "text": "And the infection? Is that from my bladder?"
    },
    {
      "turn_number": 15,
      "time": "2127-09-05 23:55:30",
      "speaker": "Doctor",
      "text": "Yes, your urine test confirmed a urinary tract infection. You got an antibiotic in the ER, and we’re switching you to a different one—Bactrim—for a five-day course."
    },
    {
      "turn_number": 16,
      "time": "2127-09-05 23:57:00",
      "speaker": "Patient",
      "text": "Okay. What about my heart medicines? I take Coumadin."
    },
    {
      "turn_number": 17,
      "time": "2127-09-05 23:58:30",
      "speaker": "Doctor",
      "text": "Your INR was high—3.6—so we’ve held your Coumadin for now. We’ll check it daily and restart when it’s safer. You’re being followed by the anticoagulation clinic after discharge."
    },
    {
      "turn_number": 18,
      "time": "2127-09-06 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 19,
      "time": "2127-09-06 08:17:00",
      "speaker": "Patient",
      "text": "Better, actually. The pain is much less. I haven’t vomited, and my belly feels softer."
    },
    {
      "turn_number": 20,
      "time": "2127-09-06 08:19:00",
      "speaker": "Doctor",
      "text": "That’s great. Your exam looks much improved—no tenderness, soft belly. We’re going to start you on clear liquids and see how you tolerate it."
    },
    {
      "turn_number": 21,
      "time": "2127-09-06 08:21:00",
      "speaker": "Patient",
      "text": "Can I have water or broth?"
    },
    {
      "turn_number": 22,
      "time": "2127-09-06 08:22:30",
      "speaker": "Doctor",
      "text": "Yes, we’ll start with sips of water and clear broth. If you do well, we’ll advance your diet slowly."
    },
    {
      "turn_number": 23,
      "time": "2127-09-06 14:30:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. Lactate was high last night—4.0—but it’s down to 2.1 today, which is reassuring. Your kidney and liver tests are normal."
    },
    {
      "turn_number": 24,
      "time": "2127-09-06 14:32:00",
      "speaker": "Patient",
      "text": "What does lactate mean?"
    },
    {
      "turn_number": 25,
      "time": "2127-09-06 14:34:00",
      "speaker": "Doctor",
      "text": "It’s a sign of how well your body is getting oxygen. High levels can mean stress on the organs, but yours is improving, which tells us your bowel is likely recovering."
    },
    {
      "turn_number": 26,
      "time": "2127-09-06 14:36:00",
      "speaker": "Patient",
      "text": "That’s good to hear."
    },
    {
      "turn_number": 27,
      "time": "2127-09-07 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. You’re doing well. We did another CT scan this morning to check the blockage."
    },
    {
      "turn_number": 28,
      "time": "2127-09-07 08:02:00",
      "speaker": "Patient",
      "text": "And? Is it still blocked?"
    },
    {
      "turn_number": 29,
      "time": "2127-09-07 08:04:00",
      "speaker": "Doctor",
      "text": "The scan shows no obstruction now. The bowel looks decompressed. That dense object may have moved or passed. You’re tolerating a regular diet without nausea—great progress."
    },
    {
      "turn_number": 30,
      "time": "2127-09-07 08:06:00",
      "speaker": "Patient",
      "text": "So I can go home?"
    },
    {
      "turn_number": 31,
      "time": "2127-09-07 08:07:30",
      "speaker": "Doctor",
      "text": "We’re planning for discharge tomorrow. A physical therapist saw you yesterday and says you’re steady on your feet—back to your usual mobility."
    },
    {
      "turn_number": 32,
      "time": "2127-09-07 08:09:00",
      "speaker": "Patient",
      "text": "I still have that chest pain on the left side. Is that okay?"
    },
    {
      "turn_number": 33,
      "time": "2127-09-07 08:11:00",
      "speaker": "Doctor",
      "text": "Yes, that’s your chronic pain, which we’ve reviewed. Your heart tests were normal—troponin and EKG—so it’s not cardiac. You’ll continue to follow up for that with your specialist."
    },
    {
      "turn_number": 34,
      "time": "2127-09-07 12:30:00",
      "speaker": "Doctor",
      "text": "Just to update you—your INR is still 3.5, so we’re keeping Coumadin held. The anticoagulation clinic will guide when to restart."
    },
    {
      "turn_number": 35,
      "time": "2127-09-07 12:32:00",
      "speaker": "Patient",
      "text": "And the antibiotics?"
    },
    {
      "turn_number": 36,
      "time": "2127-09-07 12:34:00",
      "speaker": "Doctor",
      "text": "You’ll finish the full five-day course. Take the Bactrim as prescribed, even after discharge."
    },
    {
      "turn_number": 37,
      "time": "2127-09-08 07:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re being discharged today. You’re afebrile, stable, and tolerating food well."
    },
    {
      "turn_number": 38,
      "time": "2127-09-08 07:02:00",
      "speaker": "Patient",
      "text": "That’s wonderful. Any restrictions at home?"
    },
    {
      "turn_number": 39,
      "time": "2127-09-08 07:04:00",
      "speaker": "Doctor",
      "text": "Resume your regular diet, but avoid heavy meals at first. Stay hydrated. Watch for fever, vomiting, or belly pain returning. If any, call your doctor or return here."
    },
    {
      "turn_number": 40,
      "time": "2127-09-08 07:06:00",
      "speaker": "Patient",
      "text": "And my home meds?"
    },
    {
      "turn_number": 41,
      "time": "2127-09-08 07:08:00",
      "speaker": "Doctor",
      "text": "Restart all except Coumadin. That’s on hold until the clinic advises. They’ll contact you."
    },
    {
      "turn_number": 42,
      "time": "2127-09-08 07:10:00",
      "speaker": "Patient",
      "text": "Thank you, doctor. I feel much better."
    },
    {
      "turn_number": 43,
      "time": "2127-09-08 07:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll arrange home services to check in on you. Follow up with your primary doctor in a few days."
    },
    {
      "turn_number": 44,
      "time": "2127-09-08 07:14:00",
      "speaker": "Patient",
      "text": "Got it. Thanks again."
    },
    {
      "turn_number": 45,
      "time": "2127-09-08 07:16:00",
      "speaker": "Doctor",
      "text": "Take care. We’ll see you soon in follow-up if needed."
    }
  ],
  "summary": {
    "admission_start": "2127-09-05 23:33:00",
    "admission_end": "2127-09-08 14:10:00",
    "summary_paragraph": "An elderly female with a history of chronic diastolic heart failure, hypertension, hypercholesterolemia, and recurrent DVT/PE presented with acute mid-epigastric abdominal pain, vomiting, and obstipation. Imaging revealed a partial small bowel obstruction with a 4.7 cm linear foreign body at the transition point in the distal ileum, likely the cause. She was managed conservatively with bowel rest, IV fluids, and monitoring. Her symptoms resolved, and a follow-up CT showed resolution of the obstruction. She also had a urinary tract infection, treated with antibiotics. Her INR was elevated at 3.6, so Coumadin was held and she was referred to the anticoagulation clinic. She remained hemodynamically stable, advanced to a regular diet, and was discharged home with instructions to continue antibiotics, hold anticoagulation, and follow up with her primary and specialty providers.",
    "problems": [
      "Unspecified intestinal obstruction",
      "Urinary tract infection, site not specified",
      "Chronic diastolic heart failure",
      "Congestive heart failure, unspecified",
      "Unspecified essential hypertension",
      "Pure hypercholesterolemia"
    ]
  }
}
